        StudyEvent("e5", firstStartSeconds + 4.0 * eventSpacingSeconds, riseSeconds, holdSeconds, fallSeconds),
        StudyEvent("e6", firstStartSeconds + 5.0 * eventSpacingSeconds, riseSeconds, holdSeconds, fallSeconds)
    )

    fun smooth01(value: Double): Double {
        val u = value.coerceIn(0.0, 1.0)
        return u * u * u * (10.0 + u * (-15.0 + 6.0 * u))
    }

    fun e3YRiseAge(age: Double): Double {
        // Lag grows then shrinks; the resulting local time is strictly monotonic.
        // Lag and its first two derivatives vanish at the outer endpoints.
        if (age <= 0.0 || age >= 2.0 * e3YLagHalfSpan) return age
        val lag = if (age <= e3YLagHalfSpan) {
            e3YLagPeakSeconds * smooth01(age / e3YLagHalfSpan)
        } else {
            e3YLagPeakSeconds * (1.0 - smooth01((age - e3YLagHalfSpan) / e3YLagHalfSpan))
        }
        return age - lag
    }

